class Solution { fun spiralMatrix(m:Int,n:Int,head:ListNode?):Array<IntArray>{val matrix=Array(m){IntArray(n){-1}};val directions=arrayOf(intArrayOf(0,1),intArrayOf(1,0),intArrayOf(0,-1),intArrayOf(-1,0));var row=0;var column=0;var direction=0;var node=head;while(node!=null){matrix[row][column]=node.`val`;var nr=row+directions[direction][0];var nc=column+directions[direction][1];if(nr !in 0 until m||nc !in 0 until n||matrix[nr][nc]!=-1){direction=(direction+1)%4;nr=row+directions[direction][0];nc=column+directions[direction][1]};row=nr;column=nc;node=node.next};return matrix} }
